import XCTest
@testable import Bandal

final class NativePDFLegacyInkTests: XCTestCase {
    // Golden coordinates generated from installed perfect-freehand 1.2.3 and
    // the unchanged desktop strokePath configuration, not the Swift port.
    func testLegacyShapesMatchIndependentDesktopGoldenCoordinates() throws {
        let cases = try JSONSerialization.jsonObject(with: Data(Self.golden.utf8)) as! [[String: Any]]
        for item in cases {
            let samples = item["points"] as! [[Double]]
            let row: [String: Any] = ["kind": item["hi"] as! Bool ? "highlighter" : "ink", "data": ["points": samples.map { ["x": $0[0], "y": $0[1], "p": $0[2]] }], "style": ["width": item["width"]!]]
            let path = try NativePDFLegacyInk.path(row, aspect: item["aspect"] as! Double)
            let actual = path.split(separator: " ").compactMap { Double($0) }, expected = item["expected"] as! [Double]
            XCTAssertEqual(actual.count, expected.count, item["name"] as! String)
            for (a, b) in zip(actual, expected) { XCTAssertEqual(a, b, accuracy: 1e-12, item["name"] as! String) }
        }
    }
